import { FormEvent, useState } from 'react';
import {
  JxButton,
  JxInputField,
  JxToastViewport,
  useJxToastQueue,
} from '@jinx-ui/react';

export default function NewsletterSubscribeForm() {
  const toasts = useJxToastQueue();
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);

  const trimmed = email.trim();
  const isValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed);
  const errorText =
    touched && trimmed.length > 0 && !isValid
      ? 'Укажите адрес в формате name@example.com'
      : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setTouched(true);
    if (!isValid) return;

    toasts.push({
      title: 'Готово',
      message: `Письмо с подтверждением отправлено на ${trimmed}`,
      variant: 'success',
    });
    setEmail('');
    setTouched(false);
  };

  return (
    <form
      onSubmit={submit}
      noValidate
      style={{ display: 'grid', gap: 16, maxWidth: 420 }}
    >
      <div style={{ display: 'grid', gap: 4 }}>
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            color: 'var(--jx-text)',
          }}
        >
          Подписка на рассылку
        </h2>
        <p
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-sans)',
            color: 'var(--jx-text-2)',
          }}
        >
          Раз в неделю присылаем письмо с главными обновлениями.
        </p>
      </div>

      <JxInputField
        label="Электронная почта"
        type="email"
        name="email"
        required
        autoComplete="email"
        placeholder="name@example.com"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
        onBlur={() => setTouched(true)}
        errorText={errorText}
        helperText="Отписаться можно в один клик из любого письма."
      />

      <div style={{ display: 'flex', gap: 8 }}>
        <JxButton type="submit" variant="primary" disabled={!isValid}>
          Подписаться
        </JxButton>
      </div>

      <JxToastViewport
        items={toasts.items}
        onDismiss={toasts.dismiss}
        position="bottom-right"
      />
    </form>
  );
}

